use std::fs

fn emit(text: string, number: bool, counter: int) -> int {
    let mut c = counter
    if !number {
        print(text)
        return c
    }
    let ends_nl = text.ends_with("\n")
    let parts: Vec<string> = text.split("\n").collect()
    let n: int = parts.len() as int
    let mut count = n
    if ends_nl || text.len() == 0 {
        count = n - 1
    }
    let mut i = 0
    while i < count {
        c += 1
        println("${c:>6}\t${parts[i as usize]}")
        i += 1
    }
    c
}

fn main() {
    let mut number = false
    let mut names: Vec<string> = []
    for a in std::env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if names.len() == 0 {
        let t = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(t, number, counter)
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${name}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}
